import json
import yaml

from prompty.model import DeviceAuthorization

def test_load_json_deviceauthorization():
    json_data = r'''
    {
      "deviceCode": "sample",
      "userCode": "sample",
      "verificationUri": "sample",
      "expiresIn": 1,
      "interval": 1
    }
    '''
    data = json.loads(json_data, strict=False)
    instance = DeviceAuthorization.load(data)
    assert instance is not None
    assert instance.device_code == "sample"
    assert instance.user_code == "sample"
    assert instance.verification_uri == "sample"
    assert instance.expires_in == 1
    assert instance.interval == 1

